'use strict';

/**
 * Recette seed (A-13, 10-recette.md): starts Strapi without an HTTP server, wipes then recreates
 * the recette data, and stops. Two runs give the same state.
 *
 *   DATABASE_NAME=strapi_e2e corepack pnpm@12.15.0 --dir <repo>/strapi seed
 *
 * Refuses any database whose name does not end with _e2e or _test, and NODE_ENV=production.
 * The recette data are identified by the edition slug and by the "test-" slug prefix.
 * Phase 1 creates the existing content types, the edition settings, the topics, the exhibitors, the slots
 * (generated by the slots service, like the "Régénérer" action) and the 17 attendees: the tickets of
 * fixtures/helloasso-items.json through mapItem (I-11, Q-15 decisions not applied), then the settings of recette.json,
 * plus one `welcome` EmailLog each so that a later synchronization sends nothing. No synchronization, no network, no e-mail.
 * Demonstration data (phase 2, lot 12): `bio` and `hostedTableNumber` on some attendees, the meetings and the conversations of
 * recette.json, with fixed dates. The slots are designated by their label, the people by their e-mail address. A meeting at a table
 * carries its `tableKey` ({slotDocumentId}:{tableNumber}, A-27), an accepted meeting at a stand carries "Stand {standNumber}".
 * The demonstration of 30 October runs on `strapi_demo_e2e`, loaded by this same seed (A-38).
 */

const { compileStrapi, createStrapi } = require('@strapi/strapi');
const recette = require('./fixtures/recette.json');
const tickets = require('./fixtures/helloasso-items.json');
const { mapItem } = require('../../src/api/espace/lib/import');

const EDITION_SLUG = recette.edition.slug;
const PREFIX = 'test-';
const UID = {
  edition: 'api::edition.edition',
  sequence: 'api::sequence.sequence',
  intervention: 'api::intervention.intervention',
  intervenant: 'api::intervenant.intervenant',
  organisation: 'api::organisation.organisation',
  topic: 'api::espace.topic',
  exhibitor: 'api::espace.exhibitor',
  attendee: 'api::espace.attendee',
  slot: 'api::espace.slot',
  meeting: 'api::espace.meeting',
  conversation: 'api::espace.conversation',
  message: 'api::espace.message',
  magicToken: 'api::espace.magic-token',
  emailLog: 'api::espace.email-log',
  syncRun: 'api::espace.sync-run',
};

/**
 * Guard (A-13): the seed may run only on a database whose effective name ends with _e2e or _test,
 * and never under NODE_ENV=production. Pure (no exit, no connection) so that a unit test can call it.
 */
function isSeedAllowed({ database, nodeEnv }) {
  return nodeEnv !== 'production' && /_(e2e|test)$/.test(database || '');
}

function refuse(reason) {
  console.error(`Seed refusé : ${reason}`);
  console.error('Seules les bases dont le nom finit par _e2e ou _test sont admises. Exemple :');
  console.error('  DATABASE_NAME=strapi_e2e corepack pnpm@12.15.0 --dir <dépôt>/strapi seed');
  process.exit(1);
}

async function wipe(app) {
  const remove = async (uid, filters) => {
    const documents = await app.documents(uid).findMany({ filters, limit: 1000 });
    for (const { documentId } of documents) await app.documents(uid).delete({ documentId });
  };
  // Data of the space first, children before parents: they point at the edition and the exhibitors deleted below.
  const ofEdition = { edition: { slug: EDITION_SLUG } };
  const ofAttendee = { attendee: ofEdition };
  await remove(UID.message, { conversation: ofEdition });
  await remove(UID.conversation, ofEdition);
  await remove(UID.meeting, ofEdition);
  await remove(UID.magicToken, ofAttendee);
  await remove(UID.emailLog, ofAttendee);
  await remove(UID.syncRun, ofEdition);
  await remove(UID.slot, ofEdition);
  await remove(UID.attendee, ofEdition);
  await remove(UID.exhibitor, ofEdition);
  await remove(UID.topic, ofEdition);
  await remove(UID.intervention, { sequence: { edition: { slug: EDITION_SLUG } } });
  await remove(UID.sequence, { edition: { slug: EDITION_SLUG } });
  await remove(UID.edition, { slug: EDITION_SLUG });
  await remove(UID.intervenant, { slug: { $startsWith: PREFIX } });
  await remove(UID.organisation, { slug: { $startsWith: PREFIX } });
}

async function populate(app) {
  const create = (uid, data) => app.documents(uid).create({ data, status: 'published' });
  const link = ({ documentId }) => ({ documentId });

  const organisations = {};
  for (const organisation of recette.organisations) {
    organisations[organisation.slug] = await create(UID.organisation, organisation);
  }

  const edition = await create(UID.edition, { ...recette.edition, ...recette.editionSettings });

  const sequences = {};
  const sessionsByTopic = {};
  for (const [index, { topic, ...fields }] of recette.sequences.entries()) {
    const sequence = await create(UID.sequence, { ...fields, order: index + 1, edition: link(edition) });
    sequences[fields.title] ??= sequence;
    if (topic) (sessionsByTopic[topic] ??= []).push(link(sequence));
  }

  const intervenants = {};
  for (const { organisation, sequence, ...fields } of recette.intervenants) {
    const intervenant = await create(UID.intervenant, { ...fields, organisation: link(organisations[organisation]) });
    intervenants[fields.slug] = intervenant;
    await create(UID.intervention, { sequence: link(sequences[sequence]), intervenants: [link(intervenant)], order: 0 });
  }

  const topics = {};
  for (const name of recette.topics) {
    topics[name] = await app.documents(UID.topic).create({ data: { name, edition: link(edition), sessions: sessionsByTopic[name] ?? [] } });
  }

  const exhibitors = {};
  for (const { organisation, topics: names, ...fields } of recette.exhibitors) {
    exhibitors[organisation] = await app.documents(UID.exhibitor).create({
      data: { ...fields, edition: link(edition), organisation: link(organisations[organisation]), topics: names.map((name) => link(topics[name])) },
    });
  }

  await app.service('api::espace.slots').regenerate(edition.documentId);

  // Attendees: the import mapping, then the recette settings. activatedAt and consentAt are fixed (the window opening) for the activated people.
  const activatedAt = new Date(recette.editionSettings.meetingRequestsOpenAt);
  const attendees = {};
  for (const ticket of tickets) {
    const { decision, reason, proposedRole, ...imported } = mapItem(ticket, recette.editionSettings.helloassoFieldMap);
    const { activated, topics: names, speaker, exhibitor, ...settings } = recette.attendees[imported.email];
    const attendee = await app.documents(UID.attendee).create({
      data: {
        ...imported,
        ...settings,
        ...(speaker && { speaker: link(intervenants[speaker]) }),
        ...(exhibitor && { exhibitor: link(exhibitors[exhibitor]) }),
        topics: names.map((name) => link(topics[name])),
        ...(activated && { activatedAt, consentAt: activatedAt }),
        edition: link(edition),
      },
    });
    attendees[imported.email] = attendee;
    await app.documents(UID.emailLog).create({
      data: { attendee: link(attendee), template: 'welcome', scenarioKey: 'welcome', status: 'sent', sentAt: activatedAt },
    });
  }

  // Meetings (lot 12): created as the services would leave them, without any e-mail.
  const slots = {};
  for (const slot of await app.documents(UID.slot).findMany({ filters: { edition: link(edition) }, limit: 100 })) slots[slot.label] = slot;
  for (const { requester, target, targetExhibitor, slot, tableNumber, answeredBy, ...fields } of recette.meetings) {
    await app.documents(UID.meeting).create({
      data: {
        ...fields,
        edition: link(edition),
        slot: link(slots[slot]),
        requester: link(attendees[requester]),
        ...(target && { targetAttendee: link(attendees[target]) }),
        ...(targetExhibitor && { targetExhibitor: link(exhibitors[targetExhibitor]) }),
        ...(answeredBy && { answeredBy: link(attendees[answeredBy]) }),
        ...(tableNumber && { tableNumber, tableKey: `${slots[slot].documentId}:${tableNumber}`, location: `Table ${tableNumber}` }),
        ...(targetExhibitor && fields.status === 'accepted' && { location: `Stand ${exhibitors[targetExhibitor].standNumber}` }),
      },
    });
  }

  // Conversations (lot 12): participants in the order of their ids (A-37), messages in the order of the fixture.
  for (const { participants, messages } of recette.conversations) {
    const people = participants.map((email) => attendees[email]).sort((a, b) => a.id - b.id);
    const conversation = await app.documents(UID.conversation).create({
      data: { edition: link(edition), participants: people.map(link), lastMessageAt: messages.at(-1).at },
    });
    for (const { author, at, ...fields } of messages) {
      await app.documents(UID.message).create({
        data: { ...fields, conversation: link(conversation), author: link(attendees[author]), createdAt: at },
      });
    }
  }
}

async function summarize(app, database) {
  const count = (uid, filters) => app.documents(uid).count({ filters });
  const ofEdition = { edition: { slug: EDITION_SLUG } };
  console.log(`Seed de recette terminé sur la base ${database}.`);
  console.log(`  Édition        ${await count(UID.edition, { slug: EDITION_SLUG })} (${EDITION_SLUG})`);
  console.log(`  Séquences      ${await count(UID.sequence, ofEdition)} (dont ${await count(UID.sequence, { ...ofEdition, kind: 'b2b_break' })} pauses B2B)`);
  console.log(`  Intervenants   ${await count(UID.intervenant, { slug: { $startsWith: PREFIX } })}`);
  console.log(`  Interventions  ${await count(UID.intervention, { sequence: ofEdition })}`);
  console.log(`  Organisations  ${await count(UID.organisation, { slug: { $startsWith: PREFIX } })}`);
  console.log(`  Thèmes         ${await count(UID.topic, ofEdition)}`);
  console.log(`  Exposants      ${await count(UID.exhibitor, ofEdition)}`);
  console.log(`  Créneaux       ${await count(UID.slot, ofEdition)}`);
  console.log(`  Participants   ${await count(UID.attendee, ofEdition)} (dont ${await count(UID.attendee, { ...ofEdition, status: 'cancelled' })} annulé)`);
  console.log(`  E-mails        ${await count(UID.emailLog, { attendee: ofEdition, template: 'welcome' })} (welcome)`);
  const meetings = async (status) => count(UID.meeting, { ...ofEdition, status });
  console.log(
    `  Rendez-vous    ${await count(UID.meeting, ofEdition)} (${await meetings('accepted')} acceptés, ${await meetings('pending')} en attente, ${await meetings('declined')} refusé, ${await meetings('cancelled')} annulé)`
  );
  console.log(`  Conversations  ${await count(UID.conversation, ofEdition)}`);
  console.log(
    `  Messages       ${await count(UID.message, { conversation: ofEdition })} (dont ${await count(UID.message, { conversation: ofEdition, readAt: { $null: true } })} non lus)`
  );
  console.log(`Organisateur : ${recette.organizerEmails.join(', ')} n’est pas créé, il se connecte grâce à ORGANIZER_EMAILS.`);
}

async function main() {
  if (process.env.NODE_ENV === 'production') refuse('NODE_ENV vaut production.');

  // No demo editions, no media upload on an empty database.
  process.env.DEMO_SEED = 'false';

  const app = createStrapi(await compileStrapi());
  // Strapi has read strapi/.env without overriding the shell: check the effective database before any connection.
  const database = app.config.get('database.connection.connection.database');
  if (!isSeedAllowed({ database, nodeEnv: process.env.NODE_ENV })) {
    refuse(`la base « ${database} » n’est pas une base de recette (DATABASE_NAME absent de l’environnement ou mal choisi).`);
  }

  app.log.level = 'error';
  await app.load();
  try {
    await wipe(app);
    await populate(app);
    await summarize(app, database);
  } finally {
    await app.destroy();
  }
}

module.exports = { isSeedAllowed };

if (require.main === module) {
  main().then(
    () => process.exit(0),
    (error) => {
      console.error(error);
      process.exit(1);
    }
  );
}
